mapper.update:
UPDATE reservation
SET reservation_no = #{reservationNo}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

mapper.select:
SELECT room_id AS roomId, start_time AS startTime, end_time AS endTime
FROM reservation
WHERE room_id = #{roomId}
  AND reserve_date = #{date}
  AND status IN ('PENDING', 'ONGOING')

  AND id != #{excludeId}

ORDER BY start_time

SELECT FROM reservation r JOIN `user` u ON u.id = r.user_id JOIN meeting_room m ON m.id = r.room_id
ORDER BY r.start_time DESC, r.id DESC
LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE reservation
SET status = 'CANCELLED',
    cancel_reason = #{cancelReason},
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'PENDING'

mapper.select:
SELECT COUNT(*)
FROM reservation
WHERE room_id = #{roomId}
